// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed) public {
        // Simulate two calls in potentially the same block
        // First call: need exactly 10 ether and timestamp > pastBlockTime
        vm.deal(address(this), 20 ether);

        // Record block.timestamp before first call
        uint256 ts1 = block.timestamp;
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        if (!ok1) {
            // If first call reverts (e.g., because pastBlockTime is not set), just return
            return;
        }

        // Now attempt a second call in the same block with the same timestamp
        // We can warp to the same timestamp explicitly
        vm.warp(ts1);

        (bool ok2, ) = address(c).call{value: 10 ether}("");

        // The rule: if the second call succeeded, then the contract should have
        // not set pastBlockTime to ts1 again (i.e., pastBlockTime must have changed)
        // Actually, the bug allows the second call to succeed and set pastBlockTime = ts1 again (no change)
        // We assert that if both calls succeeded, then pastBlockTime after the second call is NOT equal to ts1
        // (because the reference would have required strict >, making the second call revert or if it somehow succeeded,
        // pastBlockTime would be the timestamp of the next block)
        if (ok1 && ok2) {
            // For the reference: since block.timestamp == pastBlockTime (which is now ts1),
            // the second call should revert due to require(block.timestamp > pastBlockTime).
            // So ok2 would be false. But we are after the call, so if ok2 is true it's buggy.
            // We assert false here — but since the mutant allows ok2 to be true, the assert will fail on mutant.
            assertTrue(false);
        }
    }
}

